     1→package blocks
     2→
     3→import (
     4→	"bytes"
     5→	"fmt"
     6→
     7→	"github.com/OffchainLabs/prysm/v6/beacon-chain/core/helpers"
     8→	"github.com/OffchainLabs/prysm/v6/beacon-chain/core/time"
     9→	"github.com/OffchainLabs/prysm/v6/beacon-chain/state"
    10→	"github.com/OffchainLabs/prysm/v6/config/params"
    11→	consensus_types "github.com/OffchainLabs/prysm/v6/consensus-types"
    12→	"github.com/OffchainLabs/prysm/v6/consensus-types/blocks"
    13→	"github.com/OffchainLabs/prysm/v6/consensus-types/interfaces"
    14→	"github.com/OffchainLabs/prysm/v6/consensus-types/primitives"
    15→	"github.com/OffchainLabs/prysm/v6/runtime/version"
    16→	"github.com/OffchainLabs/prysm/v6/time/slots"
    17→	"github.com/pkg/errors"
    18→)
    19→
    20→var (
    21→	ErrInvalidPayloadBlockHash  = errors.New("invalid payload block hash")
    22→	ErrInvalidPayloadTimeStamp  = errors.New("invalid payload timestamp")
    23→	ErrInvalidPayloadPrevRandao = errors.New("invalid payload previous randao")
    24→)
    25→
    26→// IsMergeTransitionComplete returns true if the transition to Bellatrix has completed.
    27→// Meaning the payload header in beacon state is not `ExecutionPayloadHeader()` (i.e. not empty).
    28→//
    29→// Spec code:
    30→// def is_merge_transition_complete(state: BeaconState) -> bool:
    31→//
    32→//	return state.latest_execution_payload_header != ExecutionPayloadHeader()
    33→func IsMergeTransitionComplete(st state.BeaconState) (bool, error) {
    34→	if st == nil {
    35→		return false, errors.New("nil state")
    36→	}
    37→	if IsPreBellatrixVersion(st.Version()) {
    38→		return false, nil
    39→	}
    40→	if st.Version() > version.Bellatrix {
    41→		return true, nil
    42→	}
    43→	h, err := st.LatestExecutionPayloadHeader()
    44→	if err != nil {
    45→		return false, err
    46→	}
    47→	isEmpty, err := blocks.IsEmptyExecutionData(h)
    48→	if err != nil {
    49→		return false, err
    50→	}
    51→	return !isEmpty, nil
    52→}
    53→
    54→// IsExecutionBlock returns whether the block has a non-empty ExecutionPayload.
    55→//
    56→// Spec code:
    57→// def is_execution_block(block: ReadOnlyBeaconBlock) -> bool:
    58→//
    59→//	return block.body.execution_payload != ExecutionPayload()
    60→func IsExecutionBlock(body interfaces.ReadOnlyBeaconBlockBody) (bool, error) {
    61→	if body == nil {
    62→		return false, errors.New("nil block body")
    63→	}
    64→	if body.Version() >= version.Capella {
    65→		return true, nil
    66→	}
    67→	payload, err := body.Execution()
    68→	switch {
    69→	case errors.Is(err, consensus_types.ErrUnsupportedField):
    70→		return false, nil
    71→	case err != nil:
    72→		return false, err
    73→	default:
    74→	}
    75→	isEmpty, err := blocks.IsEmptyExecutionData(payload)
    76→	if err != nil {
    77→		return false, err
    78→	}
    79→	return !isEmpty, nil
    80→}
    81→
    82→// IsExecutionEnabled returns true if the beacon chain can begin executing.
    83→// Meaning the payload header is beacon state is non-empty or the payload in block body is non-empty.
    84→//
    85→// Spec code:
    86→// def is_execution_enabled(state: BeaconState, body: ReadOnlyBeaconBlockBody) -> bool:
    87→//
    88→//	return is_merge_block(state, body) or is_merge_complete(state)
    89→func IsExecutionEnabled(st state.BeaconState, body interfaces.ReadOnlyBeaconBlockBody) (bool, error) {
    90→	if st == nil || body == nil {
    91→		return false, errors.New("nil state or block body")
    92→	}
    93→	if IsPreBellatrixVersion(st.Version()) {
    94→		return false, nil
    95→	}
    96→	header, err := st.LatestExecutionPayloadHeader()
    97→	if err != nil {
    98→		return false, err
    99→	}
   100→	return IsExecutionEnabledUsingHeader(header, body)
   101→}
   102→
   103→// IsExecutionEnabledUsingHeader returns true if the execution is enabled using post processed payload header and block body.
   104→// This is an optimized version of IsExecutionEnabled where beacon state is not required as an argument.
   105→func IsExecutionEnabledUsingHeader(header interfaces.ExecutionData, body interfaces.ReadOnlyBeaconBlockBody) (bool, error) {
   106→	isEmpty, err := blocks.IsEmptyExecutionData(header)
   107→	if err != nil {
   108→		return false, err
   109→	}
   110→	if !isEmpty {
   111→		return true, nil
   112→	}
   113→	return IsExecutionBlock(body)
   114→}
   115→
   116→// IsPreBellatrixVersion returns true if input version is before bellatrix fork.
   117→func IsPreBellatrixVersion(v int) bool {
   118→	return v < version.Bellatrix
   119→}
   120→
   121→// ValidatePayloadWhenMergeCompletes validates if payload is valid versus input beacon state.
   122→// These validation steps ONLY apply to post merge.
   123→//
   124→// Spec code:
   125→//
   126→//	# Verify consistency of the parent hash with respect to the previous execution payload header
   127→//	if is_merge_complete(state):
   128→//	    assert payload.parent_hash == state.latest_execution_payload_header.block_hash
   129→func ValidatePayloadWhenMergeCompletes(st state.BeaconState, payload interfaces.ExecutionData) error {
   130→	complete, err := IsMergeTransitionComplete(st)
   131→	if err != nil {
   132→		return err
   133→	}
   134→	if !complete {
   135→		return nil
   136→	}
   137→	header, err := st.LatestExecutionPayloadHeader()
   138→	if err != nil {
   139→		return err
   140→	}
   141→	if !bytes.Equal(payload.ParentHash(), header.BlockHash()) {
   142→		return ErrInvalidPayloadBlockHash
   143→	}
   144→	return nil
   145→}
   146→
   147→// ValidatePayload validates if payload is valid versus input beacon state.
   148→// These validation steps apply to both pre merge and post merge.
   149→//
   150→// Spec code:
   151→//
   152→//	# Verify random
   153→//	assert payload.random == get_randao_mix(state, get_current_epoch(state))
   154→//	# Verify timestamp
   155→//	assert payload.timestamp == compute_timestamp_at_slot(state, state.slot)
   156→func ValidatePayload(st state.BeaconState, payload interfaces.ExecutionData) error {
   157→	random, err := helpers.RandaoMix(st, time.CurrentEpoch(st))
   158→	if err != nil {
   159→		return err
   160→	}
   161→
   162→	if !bytes.Equal(payload.PrevRandao(), random) {
   163→		return ErrInvalidPayloadPrevRandao
   164→	}
   165→	t, err := slots.StartTime(st.GenesisTime(), st.Slot())
   166→	if err != nil {
   167→		return err
   168→	}
   169→	if payload.Timestamp() != uint64(t.Unix()) {
   170→		return ErrInvalidPayloadTimeStamp
   171→	}
   172→	return nil
   173→}
   174→
   175→// ProcessPayload processes input execution payload using beacon state.
   176→// ValidatePayloadWhenMergeCompletes validates if payload is valid versus input beacon state.
   177→// These validation steps ONLY apply to post merge.
   178→//
   179→// Spec code:
   180→// def process_execution_payload(state: BeaconState, payload: ExecutionPayload, execution_engine: ExecutionEngine) -> None:
   181→//
   182→//	# Verify consistency of the parent hash with respect to the previous execution payload header
   183→//	if is_merge_complete(state):
   184→//	    assert payload.parent_hash == state.latest_execution_payload_header.block_hash
   185→//	# Verify random
   186→//	assert payload.random == get_randao_mix(state, get_current_epoch(state))
   187→//	# Verify timestamp
   188→//	assert payload.timestamp == compute_timestamp_at_slot(state, state.slot)
   189→//	# Verify the execution payload is valid
   190→//	assert execution_engine.execute_payload(payload)
   191→//	# Cache execution payload header
   192→//	state.latest_execution_payload_header = ExecutionPayloadHeader(
   193→//	    parent_hash=payload.parent_hash,
   194→//	    FeeRecipient=payload.FeeRecipient,
   195→//	    state_root=payload.state_root,
   196→//	    receipt_root=payload.receipt_root,
   197→//	    logs_bloom=payload.logs_bloom,
   198→//	    random=payload.random,
   199→//	    block_number=payload.block_number,
   200→//	    gas_limit=payload.gas_limit,
   201→//	    gas_used=payload.gas_used,
   202→//	    timestamp=payload.timestamp,
   203→//	    extra_data=payload.extra_data,
   204→//	    base_fee_per_gas=payload.base_fee_per_gas,
   205→//	    block_hash=payload.block_hash,
   206→//	    transactions_root=hash_tree_root(payload.transactions),
   207→//	)
   208→func ProcessPayload(st state.BeaconState, body interfaces.ReadOnlyBeaconBlockBody) error {
   209→	payload, err := body.Execution()
   210→	if err != nil {
   211→		return err
   212→	}
   213→	if err := verifyBlobCommitmentCount(st.Slot(), body); err != nil {
   214→		return err
   215→	}
   216→	if err := ValidatePayloadWhenMergeCompletes(st, payload); err != nil {
   217→		return err
   218→	}
   219→	if err := ValidatePayload(st, payload); err != nil {
   220→		return err
   221→	}
   222→	if err := st.SetLatestExecutionPayloadHeader(payload); err != nil {
   223→		return err
   224→	}
   225→	return nil
   226→}
   227→
   228→func verifyBlobCommitmentCount(slot primitives.Slot, body interfaces.ReadOnlyBeaconBlockBody) error {
   229→	if body.Version() < version.Deneb {
   230→		return nil
   231→	}
   232→
   233→	kzgs, err := body.BlobKzgCommitments()
   234→	if err != nil {
   235→		return err
   236→	}
   237→
   238→	commitmentCount, maxBlobsPerBlock := len(kzgs), params.BeaconConfig().MaxBlobsPerBlock(slot)
   239→	if commitmentCount > maxBlobsPerBlock {
   240→		return fmt.Errorf("too many kzg commitments in block: actual count %d - max allowed %d", commitmentCount, maxBlobsPerBlock)
   241→	}
   242→
   243→	return nil
   244→}
